from marshmallow.validate import Finite
from marshmallow.exceptions import ValidationError

# Test infinity
try:
    Finite()(float("inf"))
except ValidationError as e:
    print(f"inf rejected: {e}")

# Test negative infinity
try:
    Finite()(float("-inf"))
except ValidationError as e:
    print(f"-inf rejected: {e}")

# Test NaN
try:
    Finite()(float("nan"))
except ValidationError as e:
    print(f"nan rejected: {e}")

# Test 1e309 (which should be infinity)
try:
    Finite()(1e309)
except ValidationError as e:
    print(f"1e309 rejected: {e}")

# Test valid number
print(f"0 accepted: {Finite()(0)}")
print(f"1.5 accepted: {Finite()(1.5)}")

# Test custom error message
validator = Finite(error="Invalid: {input}")
try:
    validator(float("inf"))
except ValidationError as e:
    print(f"Custom error: {e}")
