try:
    result = Finite()(1e308)
    print(f"✓ 1e308 (large finite): {result}")
except ValidationError as e:
    print(f"✗ 1e308 rejected: {e}")

# Test very small finite numbers
try:
    result = Finite()(1e-308)
    print(f"✓ 1e-308 (small finite): {result}")
except ValidationError as e:
    print(f"✗ 1e-308 rejected: {e}")

# Test negative numbers
try:
    result = Finite()(-100)
    print(f"✓ -100 (negative): {result}")
except ValidationError as e:
    print(f"✗ -100 rejected: {e}")

# Test zero
try:
    result = Finite()(0)
    print(f"✓ 0 (zero): {result}")
except ValidationError as e:
    print(f"✗ 0 rejected: {e}")

